@Component("qualityCheck-handler")
@ProcessingGroup("qualityCheck-processing-group")
public class QualityCheckEventHandler {
	
	// core constructor
	QualityCheckEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateQualityCheckEvent
     */
    @EventHandler
    public void handle( CreateQualityCheckEvent event) {
        entityManager.persist(new QualityCheck(event.getQualityCheckId(), event.getCheckedAt(), event.getObservedValue(), event.getSampleSize(), event.getRule(), event.getDataset(), event.getStatus()));
    }

    /*
     * @param	event UpdateQualityCheckEvent
     */
    @EventHandler
    public QualityCheck handle( UpdateQualityCheckEvent event) {
    	entityManager.merge(new QualityCheck(event.getQualityCheckId(), event.getCheckedAt(), event.getObservedValue(), event.getSampleSize(), event.getRule(), event.getDataset(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteQualityCheckEvent
     */
    @EventHandler
    public void on( DeleteQualityCheckEvent event) {
    	QualityCheck entity = new QualityCheck();
   
    	// ------------------------------------------
    	// apply the QualityCheckId
    	// ------------------------------------------
    	entity.setQualityCheckId( event.getQualityCheckId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final QualityCheckRepository qualityCheckEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(QualityCheckEventHandler.class.getName());

}
